package org.mockito.internal.stubbing.answers;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CallsRealMethods.answer(InvocationOnMock invocation)
 */
public class CallsRealMethods_answer_TriageGen2Test {

    @Test
    public void testAnswerReturnsValueFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods callsRealMethods = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);
        String expectedReturnValue = "realMethodResult";

        when(invocation.callRealMethod()).thenReturn(expectedReturnValue);

        // Act
        Object actualReturnValue = callsRealMethods.answer(invocation);

        // Assert
        assertEquals(expectedReturnValue, actualReturnValue);
    }

    @Test
    public void testAnswerReturnsNullFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods callsRealMethods = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);

        when(invocation.callRealMethod()).thenReturn(null);

        // Act
        Object actualReturnValue = callsRealMethods.answer(invocation);

        // Assert
        assertNull(actualReturnValue);
    }

    @Test
    public void testAnswerThrowsExceptionFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods callsRealMethods = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);
        RuntimeException expectedException = new RuntimeException("Exception in real method");

        when(invocation.callRealMethod()).thenThrow(expectedException);

        // Act & Assert
        try {
            callsRealMethods.answer(invocation);
            org.junit.Assert.fail("Expected an exception to be thrown");
        } catch (RuntimeException e) {
            assertSame(expectedException, e);
        }
    }

    @Test
    public void testAnswerReturnsObjectInstance() throws Throwable {
        // Arrange
        CallsRealMethods callsRealMethods = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);
        Object expectedObject = new Object();

        when(invocation.callRealMethod()).thenReturn(expectedObject);

        // Act
        Object actualReturnValue = callsRealMethods.answer(invocation);

        // Assert
        assertSame(expectedObject, actualReturnValue);
    }
}
